module spot #(\n    parameter NUM_TOYS = 2,\n    parameter NUM_TREES = 1,\n    parameter signed [15:0] TOY_X [0:NUM_TOYS-1] = '{10, 10},\n    parameter signed [15:0] TOY_Y [0:NUM_TOYS-1] = '{0, 10},\n    parameter signed [15:0] TREE_X [0:NUM_TREES-1] = '{9},\n    parameter signed [15:0] TREE_Y [0:NUM_TREES-1] = '{1}\n)(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    output reg [31:0] result,\n    output reg done\n);\n    // State machine states\n    localparam [2:0] IDLE         = 3'd0;\n    localparam [2:0] SORT_TREES   = 3'd1;\n    localparam [2:0] COMPUTE      = 3'd2;\n    localparam [2:0] UPDATE_MAX   = 3'd3;\n    localparam [2:0] FINISHED     = 3'd4;\n    \n    reg [2:0] state, next_state;\n    \n    // Internal registers\n    reg [31:0] max_leash;\n    reg [31:0] current_leash;\n    reg [7:0] toy_idx;\n    reg [7:0] tree_idx;\n    reg [7:0] wrap_count;\n    reg [7:0] sort_pass;\n    \n    // Tree sorting registers\n    reg [7:0] sorted_tree_idx [0:3];\n    \n    // Fixed-point functions\n    function automatic [31:0] distance;\n        input signed [15:0] x1;\n        input signed [15:0] y1;\n        input signed [15:0] x2;\n        input signed [15:0] y2;\n        reg signed [31:0] dx, dy;\n        reg [63:0] sq;\n    begin\n        dx = x2 - x1;\n        dy = y2 - y1;\n        sq = (dx * dx) + (dy * dy);\n        distance = {sq[47:16]};  // Approximation for sqrt\n    end\n    endfunction\n    \n    function automatic angle_less;\n        input signed [15:0] tx;\n        input signed [15:0] ty;\n        input signed [15:0] ox;\n        input signed [15:0] oy;\n        reg signed [31:0] cross;\n    begin\n        cross = tx * oy - ty * ox;\n        angle_less = (cross < 0);\n    end\n    endfunction\n    \n    // Main FSM\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            max_leash <= 32'd0;\n            current_leash <= 32'd0;\n            toy_idx <= 8'd0;\n            tree_idx <= 8'd0;\n            wrap_count <= 8'd0;\n            sort_pass <= 8'd0;\n            for (i = 0; i < 4; i = i + 1) begin\n                sorted_tree_idx[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Initialize tree indices\n                        for (i = 0; i < NUM_TREES; i = i + 1) begin\n                            sorted_tree_idx[i] <= i[7:0];\n                        end\n                        state <= (NUM_TREES > 1) ? SORT_TREES : COMPUTE;\n                        max_leash <= 32'd0;\n                        toy_idx <= 8'd0;\n                        sort_pass <= 8'd0;\n                        tree_idx <= 8'd0;\n                    end\n                end\n                \n                SORT_TREES: begin\n                    if (sort_pass < NUM_TREES - 1) begin\n                        if (tree_idx < NUM_TREES - 1 - sort_pass) begin\n                            reg [7:0] idx1, idx2;\n                            reg swap_needed;\n                            idx1 = sorted_tree_idx[tree_idx];\n                            idx2 = sorted_tree_idx[tree_idx+1];\n                            swap_needed = !angle_less(TREE_X[idx1], TREE_Y[idx1], TREE_X[idx2], TREE_Y[idx2]);\n                            if (swap_needed) begin\n                                sorted_tree_idx[tree_idx] <= idx2;\n                                sorted_tree_idx[tree_idx+1] <= idx1;\n                            end\n                            tree_idx <= tree_idx + 8'd1;\n                        end else begin\n                            sort_pass <= sort_pass + 8'd1;\n                            tree_idx <= 8'd0;\n                        end\n                    end else begin\n                        state <= COMPUTE;\n                    end\n                end\n                \n                COMPUTE: begin\n                    current_leash <= 32'd0;\n                    wrap_count <= 8'd0;\n                    tree_idx <= 8'd0;\n                    state <= UPDATE_MAX;\n                end\n                \n                UPDATE_MAX: begin\n                    if (tree_idx < NUM_TREES) begin\n                        reg [7:0] t_idx;\n                        reg is_wrapped;\n                        t_idx = sorted_tree_idx[tree_idx];\n                        is_wrapped = angle_less(TREE_X[t_idx], TREE_Y[t_idx], TOY_X[toy_idx], TOY_Y[toy_idx]);\n                        \n                        if (is_wrapped) begin\n                            if (wrap_count == 8'd0) begin\n                                current_leash <= current_leash + distance(16'd0, 16'd0, TREE_X[t_idx], TREE_Y[t_idx]);\n                            end else begin\n                                reg [7:0] prev_idx;\n                                prev_idx = sorted_tree_idx[tree_idx-8'd1];\n                                current_leash <= current_leash + distance(TREE_X[prev_idx], TREE_Y[prev_idx], TREE_X[t_idx], TREE_Y[t_idx]);\n                            end\n                            wrap_count <= wrap_count + 8'd1;\n                        end\n                        tree_idx <= tree_idx + 8'd1;\n                    end else begin\n                        if (wrap_count > 8'd0) begin\n                            reg [7:0] last_idx;\n                            last_idx = sorted_tree_idx[wrap_count-8'd1];\n                            current_leash <= current_leash + distance(TREE_X[last_idx], TREE_Y[last_idx], TOY_X[toy_idx], TOY_Y[toy_idx]);\n                        end else begin\n                            current_leash <= distance(16'd0, 16'd0, TOY_X[toy_idx], TOY_Y[toy_idx]);\n                        end\n                        \n                        if (current_leash > max_leash) begin\n                            max_leash <= current_leash;\n                        end\n                        \n                        if (toy_idx < NUM_TOYS - 8'd1) begin\n                            toy_idx <= toy_idx + 8'd1;\n                            state <= COMPUTE;\n                        end else begin\n                            state <= FINISHED;\n                        end\n                    end\n                end\n                \n                FINISHED: begin\n                    result <= max_leash;\n                    done <= 1'b1;\n                    if (!start) begin\n                        state <= IDLE;\n                    end\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule